INSERT INTO lifecycle_stages (organization_id, template_id, code, name, phase_code, phase_name, position, type, target_days, weight)
SELECT t.organization_id, t.id, v.code, v.name, v.phase_code, v.phase_name, v.position, v.type, v.target_days, v.weight
FROM lifecycle_templates t, (VALUES
  ('PCN_DRAFT', 'PCN Draft', 'A', 'Initiation', 1, 'draft', 5, 2),
  ('RISK', 'Risk Assessment', 'A', 'Initiation', 2, 'assessment', 3, 2),
  ('PCN_SIGNOFF', 'PCN Sign Off', 'A', 'Initiation', 3, 'approval', 5, 2),
  ('DISCOVERY', 'Technical Discovery', 'B', 'Requirements and Design', 4, 'work', 10, 5),
  ('BRS_DRAFT', 'BRS Draft', 'B', 'Requirements and Design', 5, 'draft', 10, 5),
  ('BRS_SIGNOFF', 'BRS Sign Off', 'B', 'Requirements and Design', 6, 'approval', 5, 3),
  ('BSS_DRAFT', 'BSS Draft', 'B', 'Requirements and Design', 7, 'draft', 10, 5),
  ('BSS_SIGNOFF', 'BSS Sign Off', 'B', 'Requirements and Design', 8, 'approval', 5, 3),
  ('DEV', 'Dev Work', 'C', 'Build', 9, 'work', 40, 30),
  ('SERVERS', 'Server Allocation and Provisioning', 'C', 'Build', 10, 'work', 5, 4),
  ('SECURITY', 'Security Assessment', 'D', 'Assurance', 11, 'assessment', 5, 4),
  ('QAT', 'QATs', 'D', 'Assurance', 12, 'testing', 10, 8),
  ('UAT', 'UATs', 'D', 'Assurance', 13, 'testing', 10, 8),
  ('DEPLOY', 'Deployment', 'E', 'Release', 14, 'deployment', 3, 4),
  ('POST_DEPLOY', 'Post Deployment Testing', 'E', 'Release', 15, 'testing', 2, 3),
  ('CLOSE', 'Close Project', 'F', 'Closure', 16, 'closure', 5, 12)
) AS v (code, name, phase_code, phase_name, position, type, target_days, weight)
WHERE t.id = '0a1fec7c1e000016';
